-- =============================================================================
-- TrustGraph Synthetic Banking Engine: Production DDL & Seed Script
-- Schema: v1.2 (Strict Ground-Truth Separation Enforcement)
-- Public Tables: accounts, transactions
-- Evaluation Tables: ground_truth_accounts, ground_truth_scenarios
-- Generated: 2026-08-26
-- =============================================================================

BEGIN;

-- -----------------------------------------------------------------------------
-- 1. DDL: Table Definitions & Indexes
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS ground_truth_scenarios CASCADE;
DROP TABLE IF EXISTS ground_truth_accounts CASCADE;
DROP TABLE IF EXISTS transactions CASCADE;
DROP TABLE IF EXISTS accounts CASCADE;

-- PUBLIC VISIBLE TABLE: accounts
CREATE TABLE accounts (
    account_id VARCHAR(32) PRIMARY KEY,
    upi_id VARCHAR(100) UNIQUE NOT NULL,
    customer_name VARCHAR(100) NOT NULL,
    account_type VARCHAR(20) NOT NULL CHECK (account_type IN ('SAVINGS', 'CURRENT')),
    is_verified_merchant BOOLEAN NOT NULL DEFAULT FALSE,
    balance NUMERIC(14, 2) NOT NULL DEFAULT 0.00 CHECK (balance >= 0.00),
    risk_score NUMERIC(5, 2) NOT NULL DEFAULT 0.00,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'FLAGGED', 'FROZEN')),
    created_at TIMESTAMP NOT NULL
);

CREATE INDEX idx_accounts_upi ON accounts(upi_id);
CREATE INDEX idx_accounts_status ON accounts(status);
CREATE INDEX idx_accounts_risk ON accounts(risk_score);

-- PUBLIC VISIBLE TABLE: transactions
CREATE TABLE transactions (
    transaction_id VARCHAR(36) PRIMARY KEY,
    sender_account_id VARCHAR(32) NOT NULL REFERENCES accounts(account_id),
    receiver_account_id VARCHAR(32) NOT NULL REFERENCES accounts(account_id),
    amount NUMERIC(14, 2) NOT NULL CHECK (amount > 0.00),
    transaction_type VARCHAR(10) NOT NULL CHECK (transaction_type IN ('UPI', 'IMPS', 'NEFT')),
    status VARCHAR(10) NOT NULL DEFAULT 'SUCCESS' CHECK (status IN ('SUCCESS', 'FAILED')),
    timestamp TIMESTAMP NOT NULL
);

CREATE INDEX idx_transactions_sender ON transactions(sender_account_id);
CREATE INDEX idx_transactions_receiver ON transactions(receiver_account_id);
CREATE INDEX idx_transactions_timestamp ON transactions(timestamp);

-- HIDDEN EVALUATION TABLE: ground_truth_accounts
CREATE TABLE ground_truth_accounts (
    account_id VARCHAR(32) PRIMARY KEY REFERENCES accounts(account_id) ON DELETE CASCADE,
    archetype VARCHAR(30) NOT NULL CHECK (archetype IN (
        'NORMAL_STUDENT', 'NORMAL_SALARIED', 'NORMAL_MERCHANT',
        'VICTIM', 'MULE_L1_AGGREGATOR', 'MULE_L2_DISPERSION', 'CASH_OUT_SINK'
    )),
    is_fraud BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE INDEX idx_gt_accounts_archetype ON ground_truth_accounts(archetype);
CREATE INDEX idx_gt_accounts_is_fraud ON ground_truth_accounts(is_fraud);

-- HIDDEN EVALUATION TABLE: ground_truth_scenarios
CREATE TABLE ground_truth_scenarios (
    scenario_id VARCHAR(32) PRIMARY KEY,
    typology VARCHAR(40) NOT NULL CHECK (typology IN (
        'MULE_FAN_OUT', 'LAYERING_CHAIN', 'ACCOUNT_TAKEOVER', 'RAPID_DISPERSION'
    )),
    root_source_id VARCHAR(32) NOT NULL REFERENCES accounts(account_id),
    total_stolen_amount NUMERIC(14, 2) NOT NULL,
    start_time TIMESTAMP NOT NULL,
    end_time TIMESTAMP NOT NULL
);

-- -----------------------------------------------------------------------------
-- 2. SEED DATA: Accounts (1,000 Records)
-- -----------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- 3. SEED DATA: Transactions (32,000 Records)
-- -----------------------------------------------------------------------------

